21	function BetaModal({ onClose }: { onClose: () => void }) {
22	  const containerRef = useRef<HTMLDivElement>(null);
23	  const headingId = "beta-modal-heading";
24	
25	  // Escape key + focus trap
26	  const handleKeyDown = useCallback(
27	    (e: KeyboardEvent) => {
28	      if (e.key === "Escape") {
29	        onClose();
30	        return;
31	      }
32	      if (e.key !== "Tab" || !containerRef.current) return;
33	      const focusable = Array.from(
34	        containerRef.current.querySelectorAll<HTMLElement>(
35	          'a[href], button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])'
36	        )
37	      );
38	      if (!focusable.length) return;
39	      const first = focusable[0];
40	      const last = focusable[focusable.length - 1];
41	      if (e.shiftKey) {
42	        if (document.activeElement === first) {
43	          e.preventDefault();
44	          last.focus();
45	        }
46	      } else {
47	        if (document.activeElement === last) {
48	          e.preventDefault();
49	          first.focus();
50	        }
51	      }
52	    },
53	    [onClose]
54	  );
55	
56	  useEffect(() => {
57	    document.addEventListener("keydown", handleKeyDown);
58	    document.body.style.overflow = "hidden";
59	    // Auto-focus first focusable element
60	    const el = containerRef.current?.querySelector<HTMLElement>(
61	      'a[href], button:not([disabled])'
62	    );
63	    el?.focus();
64	    return () => {
65	      document.removeEventListener("keydown", handleKeyDown);
66	      document.body.style.overflow = "";
67	    };
68	  }, [handleKeyDown]);
69	
70	  return (
71	    <div
72	      className={styles["betaPopupOverlay"]}
73	      onClick={(e) => {
74	        if (e.target === e.currentTarget) onClose();
75	      }}
76	      role="dialog"
77	      aria-modal="true"
78	      aria-labelledby={headingId}
